from collections import Counter

def find_tiles(g):
    h,w=len(g),len(g[0])
    # each tile: rectangle where border=b, inner=f; find maximal such rects via scanning
    res=[]
    for r0 in range(h):
        for c0 in range(w):
            for bh in range(2,h-r0+1):
                for bw in range(2,w-c0+1):
                    r1,c1=r0+bh-1,c0+bw-1
                    b=g[r0][c0]
                    if b==0 or g[r0][c1]!=b or g[r1][c0]!=b or g[r1][c1]!=b: continue
                    inner=[g[r][c] for r in range(r0+1,r1) for c in range(c0+1,c1)]
                    if len(set(inner))!=1: continue
                    f=inner[0]
                    if bh>=3 and bw>=3: res.append((r0,c0,bh,bw,b,f))
    return res

def solve(g):
    t=find_tiles(g)
    cnt=Counter(t[0][5] for t in t)
    dom=cnt.most_common(1)[0][0]
    mark=[t for t in t if t[5]!=dom]
    # canonical: normalize each marker tile by removing border offset? Use tile bbox coords; paint cells strictly between aligned markers that are background.
    pts=[(r0,c0) for r0,c0,bh,bw,b,f in mark]
    out=[row[:] for row in g]
    H,W=len(g),len(g[0])
    for (r0,c0) in pts:
        r1,c1=(None,None)
    # group by row and col
    rows_=sorted(set(p[0] for p in pts)); cols_=sorted(set(p[1] for p in pts))
    def is_bg(r,c): return 0<=r<H and 0<=c<W and g[r][c]==0
    for (r0,c0) in pts:
        for (r1,c1) in pts:
            if (r0,c0)>=(r1,c1): continue
            # horizontal aligned rows? markers may share the band row: paint cells strictly between in same row
            if r0==r1 and c0!=c1:
                step=1 if c1>c0 else -1
                for c in range(c0+step,c1,step):
                    if is_bg(r0,c): out[r0][c]=g[r0][c0]  # wait paint color = marker color of either
            if c0==c1 and r0!=r1:
                step=1 if r1>r0 else -1
                for r in range(r0+step,r1,step):
