def f(g):
    h,w=len(g),len(g[0])
    cnt=collections.Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    # marker colors: rare colors appearing as small compact components; exclude frame/tiling colors
    # heuristic: colors whose total count is smallest two? decide: components of each color with size<=4 -> markers
    markers=collections.defaultdict(list)
